UPDATE community_agreements SET revision=@Revision,kind=@Kind,debtor_party_id=@DebtorPartyId,creditor_party_id=@CreditorPartyId,parent_id=@ParentId,occupancy_id=@OccupancyId,starts_on=@StartsOn,ends_on=@EndsOn,rent=@Rent,deposit=@Deposit,currency=@Currency,due_day=@DueDay,status=@Status WHERE workspace_id=@WorkspaceId AND property_id=@PropertyId AND id=@Id AND revision=@Revision-1;
